  if(!a||!SPRWRECKK[a.kind]||typeof document==='undefined') return 0;
  m=wc.getTransform(); sc=Math.hypot(m.a,m.b); if(!(sc>0)) return 0;
  S2=Math.min(1024,Math.ceil(150*sc));
  if(!SPRWRECK) SPRWRECK=document.createElement('canvas');
  if(SPRWRECK.width!==S2||SPRWRECK.height!==S2){ SPRWRECK.width=S2; SPRWRECK.height=S2; }
  x2=SPRWRECK.getContext('2d'); if(!x2) return 0;
  dx=m.a*a.x+m.c*(a.y-30)+m.e; dy=m.b*a.x+m.d*(a.y-30)+m.f;
  x2.setTransform(1,0,0,1,0,0); x2.globalCompositeOperation='source-over'; x2.globalAlpha=1; x2.clearRect(0,0,S2,S2);
  x2.setTransform(m.a,m.b,m.c,m.d,m.e-dx+S2/2,m.f-dy+S2/2);
  fl=Math.cos(a.face||0)<0?-1:1; s1=Math.min(1,f*5);
  x2.translate(a.x,a.y+3*s1+(a.kind==='snitch'?15*(a.r/SNITCH_R0):0)); x2.rotate(fl*0.12*s1); x2.translate(-a.x,-a.y);
  e={kind:a.kind,x:a.x,y:a.y,r:a.r,hp:0,maxhp:1,face:a.face||0,state:'dead',step:0,legs:0,hitT:0,muzzle:0,seenYou:false,overheat:0,wind:null,windup:null,alert:0};
  w0=wc; wc=x2;
  try{
    if(a.kind==='sentry') drawSentryS(e); else if(a.kind==='crawler') drawCrawlerS(e); else if(a.kind==='snitch') drawSnitchS(e);
    else if(a.kind==='listener') drawListenerS(e); else if(a.kind==='warden') drawWardenAt(e); else if(a.kind==='choir') drawChoirS(e);
    else if(a.kind==='howler') drawHowlerS(e); else if(a.kind==='bulwark') drawBulwarkS(e);
  }catch(_wr){} finally{ wc=w0; }
  // darken what was painted to under half its brightness, keeping its outline
  x2.setTransform(1,0,0,1,0,0); x2.globalCompositeOperation='source-atop'; x2.fillStyle='rgba(8,7,6,.56)'; x2.fillRect(0,0,S2,S2);
  x2.globalCompositeOperation='source-over';
  al=(f<0.5)?0.95:0.95*Math.max(0,1-(f-0.5)/0.5);
  wc.save(); wc.setTransform(1,0,0,1,0,0); wc.globalAlpha=al; wc.drawImage(SPRWRECK,dx-S2/2,dy-S2/2); wc.restore();
  return 1;
}
